function friendly(PDOException $e){ $m=$e->getMessage(); if(stripos($m,'Duplicate')!==false) return 'Ya existe un registro con alguno de los datos únicos proporcionados.'; if(stripos($m,'materias requisito')!==false) return 'El alumno no cumple con los prerrequisitos necesarios para esta materia.'; return 'No fue posible completar la operación. Verifica los datos y sus relaciones.'; }
try{if($_SERVER['REQUEST_METHOD']==='POST'){ $a=$_POST['accion']??'';$id=postInt('id'); if($a==='estado'){$s=$pdo->prepare('UPDATE profesores SET estado=? WHERE id=?');$s->execute([(int)$_POST['estado'],$id]);$mensaje='Estado actualizado.';} else { $v=[trim($_POST['num_empleado']??''),trim($_POST['nombre']??''),strtoupper(trim($_POST['curp']??'')),strtoupper(trim($_POST['rfc']??'')),trim($_POST['correo']??''),trim($_POST['telefono']??''),trim($_POST['especialidad']??''),$_POST['fecha_contratacion']??'',$_POST['tipo_contrato']??'']; if(!$v[0]||!$v[1]||strlen($v[2])!==18||!in_array(strlen($v[3]),[12,13])||!filter_var($v[4],FILTER_VALIDATE_EMAIL)||!in_array($v[8],['Tiempo Completo','Medio Tiempo','Asignatura'])) throw new Exception('Datos del profesor inválidos.'); if($a==='registrar'){ $pass=$_POST['password']??'';if(strlen($pass)<6)throw new Exception('La contraseña debe tener al menos 6 caracteres.');$s=$pdo->prepare('INSERT INTO profesores(num_empleado,nombre,curp,rfc,correo_institucional,telefono,especialidad,fecha_contratacion,tipo_contrato,`contraseña`,estado,rol) VALUES(?,?,?,?,?,?,?,?,?,?,1,\'profesor\')');$s->execute([...$v,password_hash($pass,PASSWORD_DEFAULT)]);$mensaje='Profesor registrado.';} if($a==='actualizar'){if(!$id)throw new Exception('Profesor inválido.');$s=$pdo->prepare('UPDATE profesores SET num_empleado=?,nombre=?,curp=?,rfc=?,correo_institucional=?,telefono=?,especialidad=?,fecha_contratacion=?,tipo_contrato=? WHERE id=?');$s->execute([...$v,$id]);$mensaje='Profesor actualizado.';} } }}catch(PDOException $e){$error=true;$mensaje=friendly($e);}catch(Exception $e){$error=true;$mensaje=$e->getMessage();}$q=trim($_GET['q']??'');$s=$pdo->prepare('SELECT * FROM profesores WHERE nombre LIKE ? OR num_empleado LIKE ? OR correo_institucional LIKE ? ORDER BY nombre');$s->execute(["%$q%","%$q%","%$q%"]);$profesores=$s->fetchAll();
